#!/usr/bin/env bash
# Regenerate .github/bindings-schema.txt for the google-genai version in
# .github/last-swept-sdk-version (or the version given as $1).
#
# The snapshot is the dump_bindings_schema.py output for that release,
# committed so offline tests can check the crate's wire keys against the
# bindings without network access (#488). Run this whenever the baseline
# moves; check_bindings_snapshot.sh (run by `make test-scripts`) fails while
# the snapshot's header and the baseline disagree.
#
# Needs network (pip download from PyPI) and python3 with pip.
#
# Usage: .github/scripts/regen_bindings_snapshot.sh [version]
set -euo pipefail

repo_root=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
version=${1:-$(tr -d '[:space:]' < "$repo_root/.github/last-swept-sdk-version")}
snapshot="$repo_root/.github/bindings-schema.txt"

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

# Same flags as the sweep: wheels only, no dependencies.
python3 -m pip download "google-genai==$version" --no-deps --only-binary=:all: -q -d "$work"
wheels=("$work"/*.whl)
if [ ! -e "${wheels[0]}" ]; then
    echo "no wheel downloaded for google-genai==$version" >&2
    exit 1
fi
python3 -m zipfile -e "${wheels[0]}" "$work/x"

gaos="$work/x/google/genai/_gaos"
if [ ! -d "$gaos/types" ]; then
    echo "bindings path not found in google-genai==$version: $gaos/types" >&2
    exit 1
fi

{
    echo "# google-genai $version"
    echo "# Generated by .github/scripts/regen_bindings_snapshot.sh; do not edit."
    python3 "$repo_root/.github/scripts/dump_bindings_schema.py" "$gaos"
} > "$snapshot.tmp"
mv "$snapshot.tmp" "$snapshot"

echo "wrote $snapshot ($(wc -l < "$snapshot") lines, google-genai $version)"
